public static string ExtractTokenFromResponse(HttpResponseMessage response)
{
    try
    {
        if (response.IsSuccessStatusCode)
        {
            var content = response.Content.ReadAsStringAsync().Result;
            var jsonDocument = JsonDocument.Parse(content);

            if (jsonDocument.RootElement.TryGetProperty("token", out var tokenElement))
            {
                return tokenElement.GetString() ?? string.Empty;
            }
            else if (jsonDocument.RootElement.TryGetProperty("access_token", out var accessTokenElement))
            {
                return accessTokenElement.GetString() ?? string.Empty;
            }
        }

        return string.Empty;
    }
    catch (Exception ex)
    {
        throw new ApplicationException($"Error extracting token: {ex.Message}", ex);
    }
}

public static async Task<bool> ValidateResponseAsync(HttpResponseMessage response, int expectedStatusCode = 200)
{
    try
    {
        // Check status code
        if (response.StatusCode != (System.Net.HttpStatusCode)expectedStatusCode)
        {
            Console.WriteLine($"Expected status {expectedStatusCode}, got {response.StatusCode}");
            return false;
        }

        // Check content type for JSON responses
        if (response.Content.Headers.ContentType?.MediaType == "application/json")
        {
            var content = await response.Content.ReadAsStringAsync();
            if (string.IsNullOrEmpty(content))
            {
                Console.WriteLine("Response content is empty");
                return false;
            }
        }

        return true;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Validation error: {ex.Message}");
        return false;
    }
}

public static T ParseJsonResponse<T>(HttpResponseMessage response)
{
    try
    {
        if (response.IsSuccessStatusCode)
        {
            var content = response.Content.ReadAsStringAsync().Result;
            return JsonSerializer.Deserialize<T>(content) ?? default(T)!;
        }

        throw new ApplicationException($"API request failed with status: {response.StatusCode}");
    }
    catch (Exception ex)
    {
        throw new ApplicationException($"Error parsing JSON response: {ex.Message}", ex);
    }
}

public static async Task<bool> ValidateResponse(HttpResponseMessage response)
{
    try
    {
        // Check if response is successful
        if (!response.IsSuccessStatusCode)
        {
            Console.WriteLine($"API call failed with status: {response.StatusCode}");
            return false;
        }

        // Check if response has content
        var content = await response.Content.ReadAsStringAsync();
        if (string.IsNullOrEmpty(content))
        {
            Console.WriteLine("Response content is empty");
            return false;
        }

        Console.WriteLine($"API call successful. Response: {content}");
        return true;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Response validation error: {ex.Message}");
        return false;
    }
}

public static async Task<string> ExtractFieldFromResponse(HttpResponseMessage response, string fieldName)
{
    var content = await response.Content.ReadAsStringAsync();
    using (var doc = JsonDocument.Parse(content))
    {
        if (doc.RootElement.TryGetProperty(fieldName, out var element))
        {
            return element.ToString();
        }
    }
    throw new KeyNotFoundException($"Field {fieldName} not found in response.");
}

